mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.4) * p.xz;
  p.yz = rot(time * 0.25) * p.yz;
  vec3 a = abs(p) - 1.0;
  float c1 = max(a.x, max(a.y, a.z));
  float c2 = max(abs(p.x) - 0.95, max(abs(p.y) - 0.95, abs(p.z) - 0.95));
  float outerFrame = max(c1, -c2);
  vec3 b = abs(p) - 0.5;
  float innerFrame = max(max(b.x, max(b.y, b.z)), -max(abs(p.x) - 0.46, max(abs(p.y) - 0.46, abs(p.z) - 0.46)));
  return min(outerFrame, innerFrame);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.2);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0;
  float glow = 0.0;
  for (int i = 0; i < 45; i++) {
    float d = map(ro + rd * t);
    glow += 0.015 / (0.05 + abs(d));
    if (d < 0.003 || t > 7.0) break;
    t += d * 0.75;
  }
  vec3 col = glow * vec3(0.1, 0.7, 1.0) * (0.8 + 0.4 * bass);
  ret = col;
}
